package config

import _ "embed"

// JSONSchemaBytes is the checked-in JSON Schema for AtomyxConfig,
// regenerated by `go run ./cmd/gen-config-schema` whenever a type in
// this package changes. A runtime consumer can serve these bytes
// directly instead of calling GenerateJSONSchema itself.
//
//go:embed atomyx-config.schema.json
var JSONSchemaBytes []byte
